import * as THREE from 'three';

export function createFurnitureEffects(scene){
  const canvas=document.createElement('canvas');canvas.width=canvas.height=16;const context=canvas.getContext('2d');context.fillStyle='#ffffff';for(const [x,y,w,h]of [[8,2,2,10],[9,2,5,2],[9,4,5,2],[4,10,6,4]])context.fillRect(x,y,w,h);
  const texture=new THREE.CanvasTexture(canvas);texture.magFilter=THREE.NearestFilter;texture.minFilter=THREE.NearestFilter;
  const material=new THREE.MeshBasicMaterial({map:texture,transparent:true,alphaTest:.2,depthWrite:false,side:THREE.DoubleSide});
  const mesh=new THREE.InstancedMesh(new THREE.PlaneGeometry(.22,.28),material,24),transform=new THREE.Object3D(),slots=Array.from({length:24},()=>({age:10,x:0,y:0,z:0,note:0}));mesh.frustumCulled=false;mesh.visible=false;scene.add(mesh);
  const puffMaterial=new THREE.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity:.8,depthWrite:false}),puffs=new THREE.InstancedMesh(new THREE.BoxGeometry(.07,.07,.07),puffMaterial,36),puffSlots=Array.from({length:36},()=>({age:10,x:0,y:0,z:0,kind:'pulse'})),color=new THREE.Color();puffs.frustumCulled=false;puffs.visible=false;scene.add(puffs);
  let cursor=0,puffCursor=0,audio=null,noise=null;const voices=[];
  function unlock(){if(!audio){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio)try{audio=new Audio();}catch{}}audio?.resume().catch(()=>{});}
  window.addEventListener('pointerdown',unlock,{passive:true});window.addEventListener('keydown',unlock,{passive:true});
  function play(point,note,listener,instrument='piano',notes=true){
    if(!listener||Math.hypot(listener.x-point.x,listener.y-point.y,listener.z-point.z)>30)return;
    note=Math.max(-12,Math.min(23,Math.floor(note)||0));const distance=Math.hypot(listener.x-point.x,listener.y-point.y,listener.z-point.z);
    if(audio?.state==='running'){
      while(voices.length>=8){const voice=voices.shift();for(const oscillator of voice.oscillators)try{oscillator.stop();}catch{}voice.gain.disconnect();}
      const drum=['drums','snare','e-drums'].includes(instrument),tap=instrument==='tap',string=['acoustic','electric','bass','ukulele','violin'].includes(instrument),duration=tap?.10:drum?.38:instrument==='harp'?1.8:string?.9:1.5,wave=drum||tap||string?'triangle':'sine',now=audio.currentTime,gain=audio.createGain(),frequency=261.625565*Math.pow(2,note/12),voice={gain,oscillators:[]};gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime((tap?.055:.10)/(1+distance*.25),now+(instrument==='violin'?.06:.006));gain.gain.exponentialRampToValueAtTime(.0001,now+duration);gain.connect(audio.destination);
      for(const [multiple,volume]of drum||tap?[[1,1],[2,.13]]:string?[[1,1],[2,.22],[3,.09]]:[[1,1],[2,.3],[3,.12]]){const oscillator=audio.createOscillator(),harmonic=audio.createGain();oscillator.type=wave;oscillator.frequency.value=frequency*multiple;harmonic.gain.value=volume;oscillator.connect(harmonic);harmonic.connect(gain);oscillator.start(now);oscillator.stop(now+duration+.06);voice.oscillators.push(oscillator);oscillator.onended=()=>{oscillator.disconnect();harmonic.disconnect();};}
      if(drum){if(!noise){noise=audio.createBuffer(1,1024,audio.sampleRate);const samples=noise.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*.18;}const source=audio.createBufferSource();source.buffer=noise;source.connect(gain);source.start(now);source.onended=()=>source.disconnect();}
      voice.oscillators[0].addEventListener('ended',()=>{gain.disconnect();const i=voices.indexOf(voice);if(i>=0)voices.splice(i,1);});voices.push(voice);
    }
    if(notes){for(let i=0;i<3;i++){const slot=slots[cursor++%24];Object.assign(slot,{age:0,x:point.x+(i-1)*.18,y:point.y,z:point.z,note:note+i});}mesh.visible=true;}
  }
  function trigger(point,kind,listener){if(!listener||Math.hypot(listener.x-point.x,listener.y-point.y,listener.z-point.z)>30)return;const tones={clock:7,seat:-5,storage:-3,cook:7,gadget:4,craft:9,aquarium:12};play(point,tones[kind]??0,listener,kind==='clock'?'harp':'tap',kind==='clock');for(let i=0;i<8;i++)Object.assign(puffSlots[puffCursor++%36],{age:0,x:point.x,y:point.y,z:point.z,kind,phase:i*2.39996});puffs.visible=true;}
  function update(dt,camera){if(mesh.visible){let count=0;for(let i=0;i<slots.length;i++){const slot=slots[i];slot.age+=dt;const alive=slot.age<1.3;if(alive)count++;transform.position.set(slot.x+Math.sin(slot.age*4+slot.note)*.12,slot.y+slot.age*.8,slot.z);transform.quaternion.copy(camera.quaternion);transform.scale.setScalar(alive?Math.min(1,(1.3-slot.age)*3):0);transform.updateMatrix();mesh.setMatrixAt(i,transform.matrix);mesh.setColorAt(i,color.setHSL(((slot.note%12)+12)%12/12,.7,.7));}mesh.instanceMatrix.needsUpdate=true;mesh.instanceColor.needsUpdate=true;mesh.visible=count>0;}
    if(puffs.visible){let count=0;for(let i=0;i<puffSlots.length;i++){const slot=puffSlots[i];slot.age+=dt;const alive=slot.age<.8;if(alive)count++;const r=slot.age*(slot.kind==='ripple'?1.2:.55);transform.position.set(slot.x+Math.sin(slot.phase)*r,slot.y+(slot.kind==='ripple'?.035:slot.age*.65),slot.z+Math.cos(slot.phase)*r);transform.rotation.set(slot.age*2,slot.phase,slot.age*3);transform.scale.setScalar(alive?(1-slot.age/.8)*(slot.kind==='plant'||slot.kind==='aquarium'?1.4:1):0);transform.updateMatrix();puffs.setMatrixAt(i,transform.matrix);puffs.setColorAt(i,color.set(slot.kind==='plant'?'#89d582':slot.kind==='light'||slot.kind==='cook'?'#ffe3a1':slot.kind==='mirror'||slot.kind==='fan'||slot.kind==='aquarium'?'#9ae7ef':slot.kind==='toy'||slot.kind==='bed'||slot.kind==='seat'?'#f7b4ce':slot.kind==='gadget'?'#a5baff':slot.kind==='craft'?'#f8c387':'#e5d6aa'));}puffs.instanceMatrix.needsUpdate=true;puffs.instanceColor.needsUpdate=true;puffs.visible=count>0;}}
  return {play,trigger,update};
}
